 vault.approveWithdraw(wReq, one);
 anchor = vault.getWithdrawalRequest(wReq).approvalTimestamp;
 assertEq(uint256(anchor), t0, "first approval anchors the deadline at t0");
 // Operator revokes. The deadline anchor survives the reopen.
 vm.prank(operator);
 vault.revokeWithdrawApproval(wReq, "logistics delay");
 assertEq(vault.getWithdrawalRequest(wReq).approvalTimestamp, anchor,
 "revoke clears status but NOT approvalTimestamp");
 // Re-approved one hour before the ORIGINAL deadline.
 vm.warp(t0 + 7 days - 1 hours);
 vm.prank(operator);
 vault.approveWithdraw(wReq, one);
 VaultTypes.WithdrawalRequest memory r = vault.getWithdrawalRequest(wReq);
 assertEq(r.approvalTimestamp, anchor, "HARM: fresh approval carries a 7-day-old deadline");
 assertEq(uint256(r.approvalTimestamp) + 7 days, block.timestamp + 1 hours,
 "HARM: the just-granted approval expires in one hour");
 // The custodian ships the bar. One hour later the customer cancels and takes the money back.
 vm.warp(t0 + 7 days + 1);
 vm.prank(alice);
 vault.cancelWithdraw(wReq);
 assertEq(troy.balanceOf(alice), TEN_OZ_1E18, "HARM: full refund after the bar shipped");
 (VaultTypes.CertificateState st,) = vault.certificatePositions(bar);
 assertEq(uint8(st), uint8(VaultTypes.CertificateState.Backing),
 "HARM: shipped bar counted as backing again");
 assertTrue(vault.onChainBackingMatchesSupply(), "protocol reports itself solvent");
